mapper.select:
SELECT COUNT(MBR_CD)
FROM BROKER
WHERE MBR_CD=#{username}

SELECT COUNT(MBR_CD)
FROM TENANCY
WHERE MBR_CD=#{username}

mapper.insert:
INSERT INTO SOLUTION_SUBSCRIPTION(
	SUBS_ID
	, MBR_CD
	, SOL_ID
	, SUBS_STARTED_AT
	, SUBS_UPDATED_DATE
	, SUBS_EXPIRATION_DATE
	, SUBS_STATUS
	, SUBS_AUTO_RENEW_YN
	, SUBS_REVOKED_AT
	, SUBS_STATUS_GRP_CD
	, SUBS_AUTO_RENEW_GRP_CD
) VALUES(
	TRIM('S')||TRIM(TO_CHAR(SEQ_SUBS_ID.NEXTVAL,'00000'))
	, #{mbrCd}
	, #{solId}
	, SYSDATE
	, #{subsUpdatedDate}
	, #{subsExpirationDate}
	, '001'
	, #{subsAutoRenewYn}
	, #{subsRevokedAt}
	, 'SBSTA'
	, 'RCPAY'
)

INSERT INTO BROKER(
	MBR_CD
	, BROK_NM
	, BROK_REG_NO
	, CRTF_NO
	, REPR_NM
	, REPR_TEL_NO
	, REG_DTM
	, BROK_ADDR2
	, BROK_ADDR1
	, AUTH_APPR_YN
	, AUTH_GRP_CD
)VALUES(
	#{mbrCd}
	, #{brokNm}
	, #{brokRegNo}
	, #{crtfNo}
	, #{reprNm}
	, #{reprTelNo}
	, #{regDtm}
	, #{brokAddr2}
	, #{brokAddr1}
	, 'W'
	, 'APST'
)

INSERT INTO TENANCY(
	RENTAL_PTY_ID
	, RENTAL_PTY_BIZ_REG_FILE_PATH
	, RENTAL_PTY_REG_BLDG_CNT
	, RENTAL_PTY_BIZ_REG_NO
	, RENTAL_PTY_FILE
	, RENTAL_PTY_FILE2
	, LSR_YN_TYPE_CD
	, MBR_CD
	, LSR_TYPE_GROUP_CD
	, AUTH_APPR_YN
	, AUTH_GRP_CD
)VALUES(
	#{rentalPtyId}
	, #{rentalPtyBizRegFilePath}
	, 0
	, #{rentalPtyBizRegNo}
	, #{rentalPtyFile}
	, #{rentalPtyFile2}
	, #{lsrYnTypeCd}
	, #{mbrCd}
	, #{lsrTypeGroupCd}
	, 'W'
	, 'APST'
)

INSERT INTO SOLUTION_SUBSCRIPTION_AUTOPAY_METHOD (
    AUTOMETH_ID
    , MBR_CD
    , AUTOMETH_PAYTYPE
    , AUTOMETH_PROVIDER
    , AUTOMETH_BILLINGKEY
    , AUTOMETH_VRTACCT
    , AUTOMETH_STARTED_AT
    , AUTOMETH_REVOKED_AT
    , AUTOMETH_IS_ACTIVE
    , AUTOMETH_PAYTYPE_GRP_CD
    , AUTOMETH_IS_ACTIVE_GRP_CD
) VALUES (
    #{automethId}
    , #{mbrCd}
    , #{automethPaytype}
    , #{automethProvider}
    , #{automethBillingkey}
    , #{automethVrtacct}
    , #{automethStartedAt}
    , #{automethRevokedAt}
    , #{automethIsActive}
    , #{automethPaytypeGrpCd}
    , #{automethIsActiveGrpCd}
)

INSERT INTO SOLUTION_SUBSCRIPTION_PAYMENT (
SUBS_PAYMENT_ID
, SUBS_ID
, AUTOMETH_ID
, BILLING_KEY
, CUSTOMER_KEY
, SUBS_PAYMENT_FAIL_MSG
, CARD_ID
, MBR_CD
) VALUES (
  #{subsPaymentId}
, #{subsId}
, #{automethId}
, #{billingKey}
, #{customerKey}
, #{subsPaymentFailMsg}
, #{cardId}
, #{mbrCd}
)

INSERT INTO ROLE_ACHIEVED (
    MBR_CD
    , USER_ROLE_ID
) VALUES (
    #{mbrCd},
    #{userRoleId}
)

INSERT INTO CARD(
	CARD_ID
	, AMOUNT
	, ISSUER_CODE
	, ACQUIRER_CODE
	, CARD_NUMBER
	, INSTALLMENT_PLAN_MONTHS
	, APPROVE_NO, USE_CARD_POINT
	, CARD_TYPE
	, OWNER_TYPE
	, ACQUIRE_STATUS
	, ISINTEREST_FREE
	, INTEREST_PAYER
	, MBR_CD
) VALUES (
	 #{cardId}
	 , #{amount}
	 , #{issuerCode}
	 , #{acquirerCode}
	 , #{cardNumber}
	 , #{installmentPlanMonths}
	 , #{approveNo}
	 , #{useCardPoint}
	 , #{cardType}
	 , #{ownerType}
	 , #{acquireStatus}
	 , #{isinterestFree}
	 , #{interestPayer}
	 , #{mbrCd}
)

INSERT INTO VIRTUAL_ACCOUNT (
    VIRTUAL_ACCOUNT_ID,
    ACCOUNT_TYPE,
    ACCOUNT_NUMBER,
    BANK_CODE,
    CUSTOMER_NAME,
    DUE_DATE,
    EXPIRED,
    SETTLEMENT_STATUS,
    SECRET,
    MBR_CD
) VALUES (
	#{virtualAccountId}
	, #{accountType}
	, #{accountNumber}
	, #{bankCode}
	, #{customerName}
	, #{dueDate}
	, #{expired}
	, #{settlementStatus}
	, #{secret}
	, #{mbrCd}
)

INSERT INTO EASY_PAY (
